INTRO = "Back at the quiet KBS variety office instead of attending his own welcome party, Baek Seung-chan gets a kind word from senior producer Ryu Il-yong before the desk phone rings. On the line is Youn Yuh-jung, calling about a jar of homemade plum tea she left on Ra Joon-mo's desk. Listen to the Korean first, then we'll go through it together."
OPENER = "Now let's go through it line by line with the English translation."
TRANSITION = "Now let's listen to the whole conversation one last time."
OUTRO = 'You heard Ryu Il-yong check in kindly at the office before Youn Yuh-jung calls about a jar of homemade plum tea she left behind. Until next time.'
CLOSING = ('actress', '다음에 봐요!')

STORY = [('ilyong', '어쨌든 나는 널 환영한다.', 'Anyway, I welcome you.', [(995, '어쨌든 나는 널 환영한다')], ''), ('seungchan', '여보세요?', 'Hello?', [(997, '여보세요?')], ''), ('actress', '나 윤여정인데요. 거기 라준모 피디 자리죠?', "This is Youn Yuh-jung. That is Producer Ra Joon-mo's desk, right?", [(998, '나 윤여정인데요'), (1000, 'PD 자리죠?')], 'Fixes caption typo 라주모 to 라준모 and spells out 피디.'), ('seungchan', '네, 맞습니다.', 'Yes, that is right.', [(1001, '네, 맞습니다')], ''), ('actress', '내가 라 피디 주려고 담근 매실차예요.', 'It is plum tea I steeped to give Producer Ra.', [(1006, '주려고 담근 매실차예요')], 'Fixes caption 나 PD to 라 피디.'), ('actress', '덕분에 재밌었다고 전해줘요.', 'Please tell him I had fun thanks to him.', [(1018, '덕분에 재밌었다고 전해줘요')], ''), ('seungchan', '네, 꼭 전해드리겠습니다.', 'Yes, I will be sure to pass that along.', [(1020, '꼭 전해드리겠습니다')], ''), ('actress', '근데 전화 받는 분은 누구신가?', 'By the way, who is answering the phone?', [(1022, '근데 전화 받는 분은 누구신가?')], ''), ('actress', '내가 너 고소하려고. 농담이야.', "I'm going to sue you. Just kidding.", [(1025, '내가 너 고소하려고'), (1027, '농담이야')], ''), ('actress', '너 이름이 뭐야?', 'What is your name?', [(1029, '너 이름이 뭐야?')], ''), ('seungchan', '백승찬입니다.', 'I am Baek Seung-chan.', [(1032, '백승찬입니다')], ''), ('actress', '그래요, 백승찬 피디. 수고했어요, 오늘.', 'All right, Producer Baek Seung-chan. Good work today.', [(1033, '그래요 백승찬 피디'), (1035, '수고했어요 오늘')], '')]

WALK = [(0, None, "'Anyway, I welcome you.'"), (1, None, "'Hello?'"), (2, None, "'This is Youn Yuh-jung. That is Producer Ra Joon-mo's desk, right?'"), (3, None, "'Yes, that is right.'"), (4, None, "'It is plum tea I steeped to give Producer Ra.'"), (5, None, "'Please tell him I had fun thanks to him.'"), (6, None, "'Yes, I will be sure to pass that along.'"), (7, None, "'By the way, who is answering the phone?'"), (8, None, "'I'm going to sue you. Just kidding.'"), (9, None, "'What is your name?'"), (10, None, "'I am Baek Seung-chan.'"), (11, None, "'All right, Producer Baek Seung-chan. Good work today.'")]
